@st.cache_data(ttl=3600, show_spinner="正在读取数据文件...")
def load_data_file(uploaded_file):
    """带缓存的数据加载函数，避免每次交互都重新读取文件"""
    file_name = (uploaded_file.name or "").lower()

    # 必须重置文件指针到开头，因为Streamlit可能会多次读取同一个文件对象
    uploaded_file.seek(0)

    if file_name.endswith('.csv'):
        try:
            return pd.read_csv(uploaded_file, encoding='utf-8-sig')
        except UnicodeDecodeError:
            uploaded_file.seek(0)
            return pd.read_csv(uploaded_file, encoding='gbk')

    if file_name.endswith('.xlsx'):
        return pd.read_excel(uploaded_file, engine='openpyxl')

    if file_name.endswith('.xls'):
        return pd.read_excel(uploaded_file, engine='xlrd')

    try:
        return pd.read_excel(uploaded_file, engine='openpyxl')
    except Exception:
        uploaded_file.seek(0)
        return pd.read_csv(uploaded_file, encoding='utf-8-sig')


def _normalize_feature_name(name):
    if not isinstance(name, str):
        return ""
    return re.sub(r"\s+", "", name.strip()).lower()


def _deduplicate_feature_list(features):
    return sanitize_feature_columns(features)


def _deduplicate_feature_list_normalized(features):
    ordered = []
    seen_text = set()
    seen_norm = set()
    for text in sanitize_feature_columns(features):
        if not text:
            continue
        norm = _normalize_feature_name(text)
        if text in seen_text or norm in seen_norm:
            continue
        seen_text.add(text)
        seen_norm.add(norm)
        ordered.append(text)
    return ordered


def _get_expected_model_feature_count(model=None, pipeline=None):
    for obj in (pipeline, model):
        if obj is None:
            continue
        try:
            n_features = getattr(obj, "n_features_in_", None)
            if n_features is not None:
                return int(n_features)
        except Exception:
            pass
    return None


def _extract_pipeline_feature_mask(pipeline):
    if pipeline is None:
        return None

    try:
        named_steps = getattr(pipeline, "named_steps", None)
        if named_steps and "feature_mask" in named_steps:
            mask = getattr(named_steps["feature_mask"], "feature_mask", None)
            if mask is not None:
                return np.asarray(mask, dtype=bool).ravel()
    except Exception:
        pass

    try:
        for step_name, step_obj in getattr(pipeline, "steps", []):
            if step_name != "feature_mask":
                continue
            mask = getattr(step_obj, "feature_mask", None)
            if mask is not None:
                return np.asarray(mask, dtype=bool).ravel()
    except Exception:
        pass

    return None


def _apply_feature_mask_to_feature_cols(feature_cols, feature_mask):
    cols = _deduplicate_feature_list(feature_values_or_empty(feature_cols))
    if not cols or feature_mask is None:
        return cols

    try:
        mask = np.asarray(feature_mask, dtype=bool).ravel()
    except Exception:
        return cols

    if len(mask) != len(cols):
        return cols

    return [col for col, keep in zip(cols, mask) if bool(keep)]


def _coerce_feature_mask(feature_mask):
    if feature_mask is None:
        return None
    try:
        return np.asarray(feature_mask, dtype=bool).ravel()
    except Exception:
        return None


def _resolve_feature_mask(train_result=None, imported_artifact=None, pipeline=None):
    train_result = train_result if isinstance(train_result, dict) else {}
    artifact = imported_artifact if isinstance(imported_artifact, dict) else {}
    artifact_extra = artifact.get("extra")
    artifact_extra = artifact_extra if isinstance(artifact_extra, dict) else {}
    candidates = (
        train_result.get("feature_mask"),
        artifact.get("feature_mask"),
        artifact_extra.get("feature_mask"),
        _extract_pipeline_feature_mask(pipeline),
        _extract_pipeline_feature_mask(artifact.get("pipeline")),
    )
    for candidate in candidates:
        normalized = _coerce_feature_mask(candidate)
        if normalized is not None:
            return normalized
    return None


def _extract_artifact_final_feature_names(artifact_extra):
    if not isinstance(artifact_extra, dict):
        return []
    workflow = artifact_extra.get("molecular_feature_workflow")
    candidates = (
        artifact_extra.get("effective_feature_cols"),
        artifact_extra.get("final_feature_names"),
        workflow.get("final_feature_names") if isinstance(workflow, dict) else None,
    )
    for candidate in candidates:
        columns = _deduplicate_feature_list_normalized(feature_values_or_empty(candidate))
        if columns:
            return columns
    return []


def _resolve_effective_feature_cols(
    train_result=None,
    selected_feature_cols=None,
    model=None,
    pipeline=None,
    imported_artifact=None,
):
    expected_n = _get_expected_model_feature_count(model=model, pipeline=pipeline)
    selected_cols = _deduplicate_feature_list_normalized(
        feature_values_or_empty(selected_feature_cols)
    )
    artifact = imported_artifact if isinstance(imported_artifact, dict) else {}
    artifact_extra = artifact.get("extra") or {}
    if not isinstance(artifact_extra, dict):
        artifact_extra = {}
    feature_mask = _resolve_feature_mask(
        train_result=train_result,
        imported_artifact=artifact,
        pipeline=pipeline,
    )

    candidates = []

    if isinstance(train_result, dict):
        for key in ("X_train", "X_train_raw", "X_test", "X_test_raw"):
            frame = train_result.get(key)
            if isinstance(frame, pd.DataFrame):
                cols = _deduplicate_feature_list(list(frame.columns))
                if cols:
                    masked_cols = _apply_feature_mask_to_feature_cols(cols, feature_mask)
                    if masked_cols:
                        candidates.append((f"train_result.{key}+feature_mask", masked_cols))
                    candidates.append((f"train_result.{key}", cols))

    artifact_effective_cols = _deduplicate_feature_list_normalized(
        feature_values_or_empty(artifact_extra.get("effective_feature_cols"))
    )
    if artifact_effective_cols:
        masked_effective_cols = _apply_feature_mask_to_feature_cols(
            artifact_effective_cols,
            feature_mask,
        )
        if masked_effective_cols:
            candidates.append(
                ("artifact.extra.effective_feature_cols+feature_mask", masked_effective_cols)
            )
        candidates.append(("artifact.extra.effective_feature_cols", artifact_effective_cols))

    artifact_workflow_cols = _extract_artifact_final_feature_names(artifact_extra)
    if artifact_workflow_cols:
        candidates.append(("artifact.extra.workflow.final_feature_names", artifact_workflow_cols))

    artifact_feature_cols = _deduplicate_feature_list_normalized(
        feature_values_or_empty(artifact.get("feature_cols"))
    )
    artifact_masked_cols = _apply_feature_mask_to_feature_cols(
        artifact_feature_cols,
        feature_mask,
    )
    if artifact_masked_cols:
        source = "artifact.feature_cols+feature_mask" if feature_mask is not None else "artifact.feature_cols"
        candidates.append((source, artifact_masked_cols))
    if artifact_feature_cols:
        candidates.append(("artifact.feature_cols", artifact_feature_cols))

    session_masked_cols = _apply_feature_mask_to_feature_cols(selected_cols, feature_mask)
    if session_masked_cols:
        source = "session.feature_cols+feature_mask" if feature_mask is not None else "session.feature_cols"
        candidates.append((source, session_masked_cols))

    model_feature_names = None
    for obj in (pipeline, model):
        if obj is None:
            continue
        try:
            model_feature_names = getattr(obj, "feature_names_in_", None)
        except Exception:
            model_feature_names = None
        if model_feature_names is not None:
            break

    if model_feature_names is None and model is not None and hasattr(model, "get_booster"):
        try:
            booster_feature_names = model.get_booster().feature_names
            if booster_feature_names is not None:
                model_feature_names = booster_feature_names
        except Exception:
            pass

    model_feature_cols = _deduplicate_feature_list_normalized(
        feature_values_or_empty(model_feature_names)
    )
    if model_feature_cols:
        candidates.append(("model.feature_names_in_", model_feature_cols))

    if selected_cols:
        candidates.append(("session.feature_cols", selected_cols))

    seen = set()
    unique_candidates = []
    for source, cols in candidates:
        key = tuple(cols)
        if not cols or key in seen:
            continue
        seen.add(key)
        unique_candidates.append((source, cols))

    chosen_source = None
    chosen_cols = []
    if expected_n is not None:
        for source, cols in unique_candidates:
            if len(cols) == expected_n:
                chosen_source = source
                chosen_cols = cols
                break

    if not chosen_cols:
        for source, cols in unique_candidates:
            if cols:
                chosen_source = source
                chosen_cols = cols
                break

    return chosen_cols, expected_n, chosen_source


def _build_screening_reference_export(
    train_result,
    effective_feature_cols,
    *,
    session_x_train_raw=None,
    session_x_train=None,
    processed_data=None,
    target_col=None,
    molecular_feature_config=None,
    max_rows=2500,
):
    """Build portable screening references from the best available training state."""
    tr = train_result if isinstance(train_result, dict) else {}
    feature_cols = sanitize_feature_columns(effective_feature_cols)
    max_rows = max(1, int(max_rows))

    def _coerce_frame(value):
        if isinstance(value, pd.DataFrame) and not value.empty:
            frame = value.copy()
            if feature_cols and all(col in frame.columns for col in feature_cols):
                return frame.loc[:, feature_cols]
            if feature_cols and frame.shape[1] == len(feature_cols):
                frame.columns = feature_cols
                return frame
            return frame
        try:
            arr = np.asarray(value)
        except Exception:
            return None
        if arr.ndim != 2 or arr.shape[0] == 0:
            return None
        if feature_cols and arr.shape[1] == len(feature_cols):
            return pd.DataFrame(arr, columns=feature_cols)
        return None

    frame = None
    for value in (
        tr.get("X_train_raw"),
        tr.get("X_train"),
        session_x_train_raw,
        session_x_train,
    ):
        frame = _coerce_frame(value)
        if frame is not None:
            break
    if frame is None and isinstance(processed_data, pd.DataFrame) and not processed_data.empty:
        if feature_cols and all(col in processed_data.columns for col in feature_cols):
            frame = processed_data.loc[:, feature_cols].copy()

    result = {}
    if frame is not None and not frame.empty:
        n_rows = len(frame)
        y_train = tr.get("y_train")
        y_num = None
        try:
            y_candidate = pd.to_numeric(pd.Series(y_train).reset_index(drop=True), errors="coerce")
            if len(y_candidate) == n_rows:
                y_num = y_candidate
        except Exception:
            y_num = None

        if n_rows > max_rows:
            priority = []
            if y_num is not None and y_num.notna().any():
                edge_n = min(100, max_rows // 5)
                priority.extend(y_num.nlargest(edge_n).index.tolist())
                priority.extend(y_num.nsmallest(edge_n).index.tolist())
            priority = list(dict.fromkeys(int(i) for i in priority))
            remaining = np.setdiff1d(np.arange(n_rows), np.asarray(priority, dtype=int), assume_unique=False)
            sample_n = max_rows - len(priority)
            if sample_n > 0:
                rng = np.random.default_rng(42)
                sampled = rng.choice(remaining, size=min(sample_n, len(remaining)), replace=False).tolist()
            else:
                sampled = []
            positions = np.asarray((priority + sampled)[:max_rows], dtype=int)
        else:
            positions = np.arange(n_rows, dtype=int)

        result["screening_reference_X"] = frame.iloc[positions].reset_index(drop=True)
        for src_key, dst_key in (
            ("y_train", "screening_reference_y_train"),
            ("y_pred_train", "screening_reference_y_pred_train"),
            ("y_std_train", "screening_reference_y_std_train"),
        ):
            value = tr.get(src_key)
            if value is None:
                continue
            try:
                arr = np.asarray(value).reshape(-1)
                if len(arr) == n_rows:
                    result[dst_key] = arr[positions]
            except Exception:
                continue

    if isinstance(processed_data, pd.DataFrame) and not processed_data.empty:
        cfg = molecular_feature_config if isinstance(molecular_feature_config, dict) else {}
        source_cols = list(cfg.get("resin_component_cols") or [])
        source_cols += list(cfg.get("hardener_component_cols") or [])
        source_cols += [cfg.get("smiles_col"), cfg.get("hardener_col"), target_col]
        keep_cols = list(dict.fromkeys(
            [col for col in source_cols + feature_cols if col and col in processed_data.columns]
        ))
        if keep_cols:
            reference_data = processed_data.loc[:, keep_cols].copy()
            if len(reference_data) > max_rows:
                if target_col in reference_data.columns:
                    target_num = pd.to_numeric(reference_data[target_col], errors="coerce")
                    high = reference_data.loc[target_num.nlargest(min(100, max_rows // 5)).index]
                    low = reference_data.loc[target_num.nsmallest(min(100, max_rows // 5)).index]
                    priority = pd.concat([high, low]).loc[lambda x: ~x.index.duplicated(keep="first")]
                else:
                    priority = reference_data.iloc[0:0]
                remaining = reference_data.drop(index=priority.index, errors="ignore")
                sample_n = max_rows - len(priority)
                sampled = remaining.sample(n=min(sample_n, len(remaining)), random_state=42) if sample_n > 0 else remaining.iloc[0:0]
                reference_data = pd.concat([priority, sampled]).head(max_rows)
            result["screening_reference_data"] = reference_data.reset_index(drop=True)
    return result


def _count_missing_like(series: pd.Series) -> int:
    if pd.api.types.is_object_dtype(series) or pd.api.types.is_string_dtype(series):
        try:
            return int(series.fillna("").astype(str).str.strip().eq("").sum())
        except Exception:
            return int(series.isna().sum())
    return int(series.isna().sum())


def _suggest_similar_feature_names(query_name: str, available_columns, limit: int = 3):
    from difflib import SequenceMatcher

    query = str(query_name or "").strip()
    if not query:
        return []

    query_norm = _normalize_feature_name(query)
    scored = []
    for col in available_columns:
        candidate = str(col)
        candidate_norm = _normalize_feature_name(candidate)
        ratio = SequenceMatcher(None, query_norm, candidate_norm).ratio()
        if query_norm and (query_norm in candidate_norm or candidate_norm in query_norm):
            ratio = max(ratio, 0.82)
        if ratio >= 0.45:
            scored.append((ratio, candidate))

    scored.sort(key=lambda item: (-item[0], item[1]))
    result = []
    seen = set()
    for _, name in scored:
        if name in seen:
            continue
        seen.add(name)
        result.append(name)
        if len(result) >= limit:
            break
    return result


def _resolve_prediction_feature_cols(model=None, pipeline=None, session_feature_cols=None, imported_artifact=None):
    """Resolve the most reliable feature list for prediction."""
    expected_n = None
    for obj in (pipeline, model):
        if obj is None:
            continue
        try:
            n_features = getattr(obj, "n_features_in_", None)
            if n_features is not None:
                expected_n = int(n_features)
                break
        except Exception:
            pass

    def _clean(cols):
        return _deduplicate_feature_list(cols)

    candidates = []
    artifact = imported_artifact or {}
    if isinstance(artifact, dict):
        candidates.append(
            (
                "artifact.feature_cols",
                _clean(feature_values_or_empty(artifact.get("feature_cols"))),
            )
        )

    model_feature_names = None
    for obj in (pipeline, model):
        if obj is None:
            continue
        try:
            model_feature_names = getattr(obj, "feature_names_in_", None)
        except Exception:
            model_feature_names = None
        if model_feature_names is not None:
            break

    if model_feature_names is None and model is not None and hasattr(model, "get_booster"):
        try:
            booster_feature_names = model.get_booster().feature_names
            if booster_feature_names is not None:
                model_feature_names = booster_feature_names
        except Exception:
            pass

    candidates.append(("model.feature_names_in_", _clean(feature_values_or_empty(model_feature_names))))
    candidates.append(("session.feature_cols", _clean(feature_values_or_empty(session_feature_cols))))

    chosen_source = None
    chosen_cols = []
    if expected_n is not None:
        for source, cols in candidates:
            if cols and len(cols) == expected_n:
                chosen_source = source
                chosen_cols = cols
                break

    if not chosen_cols:
        for source, cols in candidates:
            if cols:
                chosen_source = source
                chosen_cols = cols
                break

    note = None
    session_cols = _clean(feature_values_or_empty(session_feature_cols))
    if expected_n is not None:
        if len(chosen_cols) != expected_n:
            note = f"模型要求 {expected_n} 个特征，但当前可解析到的特征列表是 {len(chosen_cols)} 个。"
        elif session_cols and len(session_cols) != expected_n and chosen_source != "session.feature_cols":
            note = f"当前会话特征数是 {len(session_cols)}，与模型要求的 {expected_n} 不一致，已自动改用 {chosen_source}。"
    elif chosen_source and chosen_source != "session.feature_cols":
        note = f"已优先使用 {chosen_source} 作为预测特征列表。"

    return chosen_cols, expected_n, note


def _build_feature_alignment_report(input_df: pd.DataFrame, required_features):
    required_features = _deduplicate_feature_list(required_features)
    available_columns = sanitize_feature_columns(input_df.columns)
    available_map = {}
    for col in available_columns:
        available_map.setdefault(_normalize_feature_name(col), []).append(col)

    matched_rows = []
    missing_rows = []
    incomplete_rows = []
    matched_source_columns = set()

    for feature in required_features:
        feature_norm = _normalize_feature_name(feature)
        matches = available_map.get(feature_norm, [])
        if matches:
            source_col = matches[0]
            matched_source_columns.add(source_col)
            missing_count = _count_missing_like(input_df[source_col])
            missing_ratio = (missing_count / len(input_df) * 100.0) if len(input_df) else 0.0
            row = {
                "required_feature": feature,
                "source_column": source_col,
                "missing_count": missing_count,
                "missing_ratio": round(missing_ratio, 2),
                "renamed": source_col != feature,
            }
            matched_rows.append(row)
            if missing_count > 0:
                incomplete_rows.append(row)
        else:
            missing_rows.append(
                {
                    "missing_feature": feature,
                    "suggestions": ", ".join(_suggest_similar_feature_names(feature, available_columns, limit=3)),
                }
            )

    extra_columns = [col for col in available_columns if col not in matched_source_columns]
    return {
        "required_features": required_features,
        "available_columns": available_columns,
        "matched_rows": matched_rows,
        "missing_rows": missing_rows,
        "incomplete_rows": incomplete_rows,
        "extra_columns": extra_columns,
    }


def _align_input_dataframe_to_required_features(input_df: pd.DataFrame, required_features):
    report = _build_feature_alignment_report(input_df, required_features)
    aligned_df = pd.DataFrame(index=input_df.index)
    auto_renamed = []
    for row in report["matched_rows"]:
        required_feature = row["required_feature"]
        source_column = row["source_column"]
        aligned_df[required_feature] = input_df[source_column]
        if source_column != required_feature:
            auto_renamed.append((required_feature, source_column))
    return aligned_df, report["missing_rows"], auto_renamed, report


def _render_prediction_feature_check_panel(input_df: pd.DataFrame, required_features, panel_key: str):
    if input_df is None or input_df.empty or not required_features:
        return

    report = _build_feature_alignment_report(input_df, required_features)
    matched_count = len(report["matched_rows"])
    missing_count = len(report["missing_rows"])
    extra_count = len(report["extra_columns"])
    coverage = matched_count / max(1, len(report["required_features"])) * 100.0

    with st.expander("特征搜索与补齐提醒", expanded=True):
        c1, c2, c3, c4 = st.columns(4)
        c1.metric("模型所需特征", len(report["required_features"]))
        c2.metric("已匹配", matched_count)
        c3.metric("缺失列", missing_count)
        c4.metric("覆盖率", f"{coverage:.1f}%")

        search_query = st.text_input(
            "搜索导入数据中的特征",
            key=f"{panel_key}_feature_search",
            placeholder="输入特征名、关键字或前缀",
        ).strip()
        if search_query:
            query_norm = _normalize_feature_name(search_query)
            contains_matches = [col for col in report["available_columns"] if query_norm in _normalize_feature_name(col)]
            fuzzy_matches = _suggest_similar_feature_names(search_query, report["available_columns"], limit=20)
            merged_matches = []
            seen = set()
            for col in contains_matches + fuzzy_matches:
                if col not in seen:
                    seen.add(col)
                    merged_matches.append(col)
            if merged_matches:
                st.dataframe(
                    pd.DataFrame({"匹配列": merged_matches}),
                    width="stretch",
                    hide_index=True,
                    height=min(420, 36 * len(merged_matches) + 38),
                )
            else:
                st.warning("当前导入数据中没有找到相关列。")

        if report["missing_rows"]:
            missing_df = pd.DataFrame(report["missing_rows"]).rename(
                columns={"missing_feature": "缺失特征", "suggestions": "可能对应列"}
            )
            st.warning(f"检测到 {len(missing_df)} 个模型必需特征缺失，建议先补齐再预测。")
            st.dataframe(
                missing_df,
                width="stretch",
                hide_index=True,
                height=min(420, 36 * len(missing_df) + 38),
            )
            st.download_button(
                "下载缺失特征清单",
                data=missing_df.to_csv(index=False).encode("utf-8-sig"),
                file_name="missing_prediction_features.csv",
                mime="text/csv",
                key=f"{panel_key}_missing_features_download",
            )
        else:
            st.success("模型必需特征列已全部找到。")

        if report["incomplete_rows"]:
            incomplete_df = pd.DataFrame(report["incomplete_rows"]).rename(
                columns={
                    "required_feature": "模型特征",
                    "source_column": "导入列",
                    "missing_count": "空值数",
                    "missing_ratio": "空值比例(%)",
                }
            )[["模型特征", "导入列", "空值数", "空值比例(%)"]]
            st.warning(f"其中 {len(incomplete_df)} 个已匹配特征存在空值/空字符串，建议补齐。")
            st.dataframe(
                incomplete_df,
                width="stretch",
                hide_index=True,
                height=min(420, 36 * len(incomplete_df) + 38),
            )

        if extra_count > 0:
            st.caption(f"导入数据中还有 {extra_count} 列不是当前模型所需特征。预测时会自动忽略这些额外列。")

