# ============================================================
# Session Snapshot (disconnect protection)
# ============================================================
def _normalize_meta_value(val):
    if isinstance(val, np.generic):
        return val.item()
    if isinstance(val, dict):
        return {k: _normalize_meta_value(v) for k, v in val.items()}
    if isinstance(val, (list, tuple, set)):
        return [_normalize_meta_value(v) for v in val]
    return val


def _get_or_create_session_id() -> str:
    sid = st.session_state.get("_sid")
    if not sid:
        sid = uuid.uuid4().hex[:12]
        st.session_state["_sid"] = sid
    return sid


def _snapshot_paths(tag: str = "latest"):
    safe_tag = "".join(c if (c.isalnum() or c in ("-", "_")) else "_" for c in str(tag))
    base = os.path.join(SESSION_SNAPSHOT_DIR, safe_tag)
    meta_path = f"{base}.json"
    df_paths = {k: f"{base}_{k}.csv" for k in _SNAPSHOT_DF_KEYS}
    return meta_path, df_paths


def _load_snapshot_meta(tag: str = "latest"):
    meta_path, _ = _snapshot_paths(tag)
    if not os.path.isfile(meta_path):
        return None
    try:
        with open(meta_path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _save_session_snapshot(tag: str = "latest") -> tuple:
    os.makedirs(SESSION_SNAPSHOT_DIR, exist_ok=True)
    meta_path, df_paths = _snapshot_paths(tag)

    if st.session_state.get("data") is None and st.session_state.get("processed_data") is None:
        return False, "no_data"

    saved_df_keys = []
    df_info = {}
    for key in _SNAPSHOT_DF_KEYS:
        df = st.session_state.get(key)
        if isinstance(df, pd.DataFrame):
            try:
                df.to_csv(df_paths[key], index=False, encoding="utf-8-sig")
                saved_df_keys.append(key)
                df_info[key] = {"rows": int(len(df)), "cols": int(len(df.columns))}
            except Exception:
                continue

    meta = {
        "version": SESSION_SNAPSHOT_VERSION,
        "saved_at": datetime.now().isoformat(timespec="seconds"),
        "app_version": VERSION,
        "sid": _get_or_create_session_id(),
        "df_keys": saved_df_keys,
        "df_info": df_info,
    }
    for key in _SNAPSHOT_META_KEYS:
        meta[key] = _normalize_meta_value(st.session_state.get(key))

    try:
        with open(meta_path, "w", encoding="utf-8") as f:
            json.dump(meta, f, ensure_ascii=False, indent=2, default=str)
    except Exception:
        return False, "meta_write_failed"

    st.session_state["_last_autosave_ts"] = time.time()
    return True, "ok"


def _should_restore_value(val) -> bool:
    if val is None:
        return True
    if isinstance(val, (list, tuple, dict)) and len(val) == 0:
        return True
    return False


def _restore_session_snapshot(tag: str = "latest", override: bool = False) -> tuple:
    meta = _load_snapshot_meta(tag)
    if not meta:
        return False, "no_snapshot"
    snapshot_sid = meta.get("sid")
    current_sid = _get_or_create_session_id()
    if (
        mapping_snapshot_restore_policy(
            meta,
            current_session_id=current_sid,
        )
        == "session_mismatch"
    ):
        return False, "session_mismatch"

    _, df_paths = _snapshot_paths(tag)
    for key in _SNAPSHOT_DF_KEYS:
        if key not in (meta.get("df_keys") or []):
            continue
        if (not override) and (not _should_restore_value(st.session_state.get(key))):
            continue
        path = df_paths.get(key)
        if not path or (not os.path.isfile(path)):
            continue
        try:
            st.session_state[key] = pd.read_csv(path, encoding='utf-8-sig')
        except Exception:
            continue

    for key in _SNAPSHOT_META_KEYS:
        if key not in meta:
            continue
        if (not override) and (not _should_restore_value(st.session_state.get(key))):
            continue
        st.session_state[key] = meta.get(key)

    # 优化结果包含不可序列化的 Optuna study，只保留在当前运行会话中。
    # 旧快照可能保存过字符串化对象，恢复时必须清空，不能让页面误当作结果对象使用。
    st.session_state["optimization_result"] = None
    st.session_state["best_score"] = None

    try:
        snapshot_version = int(meta.get("version") or 1)
    except (TypeError, ValueError):
        snapshot_version = 1
    if snapshot_version < 2 or "molecular_feature_workflow" not in meta or "molecular_feature_trace" not in meta:
        _clear_molecular_feature_session_metadata()
    if mapping_snapshot_restore_policy(
        meta,
        current_session_id=current_sid,
    ) == "clear":
        _clear_post_feature_mapping_session_metadata()

    st.session_state["_snapshot_loaded"] = True
    st.session_state["_snapshot_loaded_at"] = meta.get("saved_at")
    return True, "ok"


def _clear_molecular_feature_session_metadata():
    st.session_state["molecular_feature_workflow"] = None
    st.session_state["molecular_feature_trace"] = []
    _clear_post_feature_mapping_session_metadata()


def _clear_process_pls_session_metadata():
    st.session_state["process_pls_workflow"] = None
    st.session_state["process_pls_preview_report"] = None
    st.session_state["process_pls_enabled_default"] = False
    st.session_state["process_pls_use_in_training"] = False


def _restore_process_pls_metadata(payload):
    from core.model_io import restore_process_pls_metadata

    workflow = restore_process_pls_metadata(payload)
    if workflow is None:
        _clear_process_pls_session_metadata()
        return None
    st.session_state["process_pls_workflow"] = workflow
    st.session_state["process_pls_enabled_default"] = bool(workflow.get("enabled"))
    st.session_state["process_pls_use_in_training"] = False
    return workflow


def _clear_post_feature_mapping_session_metadata():
    st.session_state["post_feature_mapping_default"] = None
    st.session_state["post_feature_mapping_draft"] = None
    st.session_state["post_feature_mapping_confirmation"] = False
    st.session_state["post_feature_mapping_model_fingerprint"] = None
    st.session_state["post_feature_mapping_catalog_fingerprint"] = None
    st.session_state["post_feature_mapping_snapshot"] = None


def _post_feature_mapping_model_fingerprint(model_feature_cols):
    payload = sanitize_feature_columns(model_feature_cols)
    return hashlib.sha256(
        json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    ).hexdigest()


def _post_feature_mapping_catalog_fingerprint(catalog):
    return catalog_fingerprint(catalog)


def _restore_post_feature_mapping_metadata(payload, model_feature_cols=None):
    extra = payload.get("extra") if isinstance(payload, dict) else None
    extra = extra if isinstance(extra, dict) else {}
    default = (
        extra.get("post_feature_mapping_default")
        if "post_feature_mapping_default" in extra
        else payload.get("post_feature_mapping_default")
        if isinstance(payload, dict)
        else None
    )
    _clear_post_feature_mapping_session_metadata()
    if not isinstance(default, dict):
        return

    raw_default = copy.deepcopy(default)
    default = normalize_mapping(raw_default)
    for metadata_key in ("mapping_hash", "confirmed_at"):
        metadata_value = raw_default.get(metadata_key)
        if isinstance(metadata_value, str):
            default[metadata_key] = metadata_value
    model_fingerprint = _post_feature_mapping_model_fingerprint(
        model_feature_cols or default.get("model_feature_cols") or []
    )
    stored_model_fingerprint = default.get("model_fingerprint") or model_fingerprint
    stored_catalog_fingerprint = default.get("catalog_fingerprint")
    st.session_state["post_feature_mapping_default"] = default
    st.session_state["post_feature_mapping_draft"] = copy.deepcopy(default)
    st.session_state["post_feature_mapping_confirmation"] = False
    st.session_state["post_feature_mapping_model_fingerprint"] = stored_model_fingerprint
    st.session_state["post_feature_mapping_catalog_fingerprint"] = stored_catalog_fingerprint


def _invalidate_post_feature_mapping_if_changed(model_feature_cols, catalog_fp):
    draft = st.session_state.get("post_feature_mapping_draft")
    if not isinstance(draft, dict):
        return False

    current_model_fp = _post_feature_mapping_model_fingerprint(model_feature_cols)
    previous_model_fp = st.session_state.get(
        "post_feature_mapping_model_fingerprint"
    ) or draft.get("model_fingerprint")
    if previous_model_fp is None and draft.get("model_feature_cols") is not None:
        previous_model_fp = _post_feature_mapping_model_fingerprint(
            draft.get("model_feature_cols")
        )
    previous_catalog_fp = st.session_state.get(
        "post_feature_mapping_catalog_fingerprint"
    ) or draft.get("catalog_fingerprint")
    changed = (
        previous_model_fp is not None and previous_model_fp != current_model_fp
    ) or (
        previous_catalog_fp is not None and previous_catalog_fp != catalog_fp
    )
    st.session_state["post_feature_mapping_model_fingerprint"] = current_model_fp
    st.session_state["post_feature_mapping_catalog_fingerprint"] = catalog_fp
    if not changed:
        return False

    draft["invalid"] = True
    st.session_state["post_feature_mapping_confirmation"] = False
    return True


def _post_feature_mapping_snapshot_for_screening():
    draft = st.session_state.get("post_feature_mapping_draft")
    if (
        not isinstance(draft, dict)
        or not st.session_state.get("post_feature_mapping_confirmation", False)
        or draft.get("invalid")
    ):
        return None
    return mapping_snapshot(draft)


def _prepare_post_feature_mapping_for_prediction(
    *,
    model_feature_cols,
    molecular_feature_cols,
    candidate_df,
    computed_definitions,
    missing_input_tolerant,
    panel_key,
):
    """Shared ordinary/formulation prediction gate; never creates a post-prediction snapshot."""
    if not model_feature_cols:
        empty_catalog = build_post_feature_catalog(
            candidate_df,
            computed_definitions=computed_definitions,
            excluded_columns={
                "resin_smiles",
                "hardener_smiles",
                "combo_smiles",
                "candidate_origin",
                "formulation_id",
            },
        )
        return None, {
            "ok": True,
            "status": "not_required",
            "errors": [],
            "warnings": [],
            "mapped_feature_cols": [],
            "mapping_hash": None,
            "catalog_fingerprint": catalog_fingerprint(empty_catalog),
        }, empty_catalog
    catalog = build_post_feature_catalog(
        candidate_df,
        computed_definitions=computed_definitions,
        excluded_columns={
            "resin_smiles",
            "hardener_smiles",
            "combo_smiles",
            "candidate_origin",
            "formulation_id",
        },
    )
    confirmed_mapping, report = _render_post_feature_mapping_panel(
        model_feature_cols=list(model_feature_cols),
        molecular_feature_cols=list(molecular_feature_cols or []),
        candidate_df=candidate_df,
        workflow_fingerprint=(st.session_state.get("molecular_feature_workflow", {}) or {}).get("workflow_hash"),
        model_fingerprint=_post_feature_mapping_model_fingerprint(model_feature_cols),
        missing_input_tolerant=bool(missing_input_tolerant),
        panel_key=panel_key,
    )
    if confirmed_mapping is None or not report.get("ok"):
        return None, report, catalog
    return confirmed_mapping, report, catalog


def _render_post_feature_mapping_panel(
    *,
    model_feature_cols: list[str],
    molecular_feature_cols: list[str],
    candidate_df: pd.DataFrame,
    workflow_fingerprint: str | None,
    model_fingerprint: str,
    missing_input_tolerant: bool,
    panel_key: str,
) -> tuple[dict | None, dict]:
    """渲染简洁的筛选前人工映射区，未确认时返回 (None, report)。"""
    excluded_columns = {
        "resin_smiles", "hardener_smiles", "combo_smiles", "candidate_origin",
        "formulation_id", "_molecule_key",
    }
    catalog = build_post_feature_catalog(
        candidate_df,
        computed_definitions=POST_FEATURE_COMPUTED_DEFINITIONS,
        excluded_columns=excluded_columns,
    )
    catalog_fp = catalog_fingerprint(catalog)
    model_cols, rejected_types = sanitize_feature_columns(
        model_feature_cols,
        return_rejected=True,
    )
    if rejected_types:
        st.warning(
            "模型特征列表中检测到无效记录，已忽略后继续。"
        )
    if not model_cols:
        return None, {
            "ok": True, "status": "not_required", "errors": [], "warnings": [],
            "mapped_feature_cols": [], "mapping_hash": None,
            "catalog_fingerprint": catalog_fp,
        }

    prefix = f"post_feature_mapping_{panel_key}"
    draft_key = f"{prefix}_draft"
    confirmed_key = f"{prefix}_confirmed"
    previous = st.session_state.get(draft_key)
    stale_draft = isinstance(previous, dict) and (
        previous.get("model_fingerprint") != model_fingerprint
        or previous.get("catalog_fingerprint") != catalog_fp
    )
    if not isinstance(previous, dict) or stale_draft:
        previous = create_mapping_draft(
            model_cols,
            molecular_feature_cols=molecular_feature_cols,
            catalog=catalog,
            model_fingerprint=model_fingerprint,
            workflow_fingerprint=workflow_fingerprint,
        )
        st.session_state[draft_key] = previous
        st.session_state[confirmed_key] = False
        st.session_state.pop(f"{prefix}_manual_features", None)
        for feature in model_cols:
            st.session_state.pop(f"{prefix}_{feature}_source_choice", None)
            st.session_state.pop(f"{prefix}_{feature}_constant", None)
    draft = copy.deepcopy(previous)
    draft["model_feature_cols"] = model_cols
    draft["model_fingerprint"] = model_fingerprint
    draft["workflow_fingerprint"] = workflow_fingerprint
    draft["catalog_fingerprint"] = catalog_fp

    choices = build_manual_mapping_choices(
        catalog,
        include_constant=True,
        include_unused=bool(missing_input_tolerant),
    )
    choice_labels = [choice["label"] for choice in choices]

    mapping_panel = st.expander("筛选前确认：模型特征来源", expanded=True)
    mapping_panel.caption(
        f"模型共有 {len(model_cols)} 个特征；默认保留候选配方已有值，"
        "只对需要改变的特征手动设置来源。系统不会按同名列自动匹配。"
    )
    if catalog.empty:
        mapping_panel.warning(
            "当前候选池没有可供映射的数值列，请先检查配方特征或改用常数值。"
        )

    previous_rules = previous.get("rules") if isinstance(previous, dict) else {}
    previous_manual_features = [
        feature
        for feature in model_cols
        if (previous_rules or {}).get(feature, {}).get("source_type")
        not in {None, "pending", "keep"}
    ]
    with mapping_panel.form(key=f"{prefix}_form", clear_on_submit=False):
        manual_features = st.multiselect(
            "选择需要手动改变的模型特征（可不选）",
            options=model_cols,
            default=previous_manual_features,
            key=f"{prefix}_manual_features",
            help="未选中的特征将保留当前候选配方已有值，不会自动匹配同名列。",
        )
        manual_feature_set = set(manual_features)
        if not manual_features:
            st.info("当前未选择需要改变的特征；点击“确认映射并继续”即可保留现有值。")

        updated_rules = {}
        for feature in model_cols:
            rule = (draft.get("rules") or {}).get(feature) or {}
            if feature not in manual_feature_set:
                updated_rules[feature] = {
                    "source_type": "keep",
                    "source_column": None,
                    "constant_value": None,
                    "unit": None,
                    "definition": None,
                    "confirmed": False,
                }
                continue
            selected_index = 0
            for choice_index, choice in enumerate(choices):
                if (
                    choice["source_type"] == rule.get("source_type")
                    and choice["source_column"] == rule.get("source_column")
                ):
                    selected_index = choice_index
                    break
            row = st.columns([1.1, 2.9])
            row[0].markdown(f"**{feature}**")
            selected_label = row[1].selectbox(
                "来源",
                choice_labels,
                index=selected_index,
                key=f"{prefix}_{feature}_source_choice",
                label_visibility="collapsed",
            )
            selected_choice = choices[choice_labels.index(selected_label)]
            constant_value = None
            if selected_choice["source_type"] == "constant":
                constant_default = 0.0
                try:
                    candidate_constant = float(rule.get("constant_value"))
                    if np.isfinite(candidate_constant):
                        constant_default = candidate_constant
                except (TypeError, ValueError):
                    pass
                constant_value = row[1].number_input(
                    "常数值",
                    value=constant_default,
                    key=f"{prefix}_{feature}_constant",
                    label_visibility="visible",
                )
            updated_rules[feature] = {
                "source_type": selected_choice["source_type"],
                "source_column": selected_choice["source_column"],
                "constant_value": constant_value,
                "unit": rule.get("unit"),
                "definition": rule.get("definition"),
                "confirmed": False,
            }

        action_col, clear_col = st.columns([1, 1])
        confirm_clicked = action_col.form_submit_button(
            "确认映射并继续",
            type="primary",
            width="stretch",
        )
        clear_clicked = clear_col.form_submit_button(
            "清空选择",
            width="stretch",
        )

    edited_draft = copy.deepcopy(draft)
    edited_draft["rules"] = updated_rules
    edited_draft["confirmed"] = False
    edited_draft["status"] = "draft"
    if clear_clicked:
        blank = create_mapping_draft(
            model_cols,
            molecular_feature_cols=[],
            catalog=catalog,
            model_fingerprint=model_fingerprint,
            workflow_fingerprint=workflow_fingerprint,
        )
        st.session_state[draft_key] = blank
        st.session_state[confirmed_key] = False
        for feature in model_cols:
            st.session_state.pop(f"{prefix}_{feature}_source_choice", None)
            st.session_state.pop(f"{prefix}_{feature}_constant", None)
        st.rerun()
    if confirm_clicked:
        draft = commit_mapping_form_draft(
            previous,
            edited_draft,
            submitted=True,
        )
        for rule in draft["rules"].values():
            rule["confirmed"] = True
        draft["confirmed"] = True
        draft["status"] = "confirmed"
        report = validate_mapping(
            draft,
            model_feature_cols=model_cols,
            candidate_df=candidate_df,
            catalog=catalog,
            missing_input_tolerant=missing_input_tolerant,
        )
        st.session_state[draft_key] = draft if report.get("ok") else {**draft, "confirmed": False, "status": "draft"}
        st.session_state[confirmed_key] = bool(report.get("ok"))
    active = st.session_state.get(draft_key, previous)
    report = validate_mapping(
        active,
        model_feature_cols=model_cols,
        candidate_df=candidate_df,
        catalog=catalog,
        missing_input_tolerant=missing_input_tolerant,
    )
    if not st.session_state.get(confirmed_key, False):
        report["ok"] = False
        report["errors"] = list(report.get("errors") or [])
    if report.get("ok"):
        mapping_panel.success(f"已确认 {len(model_cols)} 个特征来源，可以继续筛选。")
    elif confirm_clicked:
        mapping_panel.error("映射未通过检查：请为每个特征选择有效的数值来源列。")
    else:
        pending_features = [
            feature
            for feature, rule in updated_rules.items()
            if rule.get("source_type") == "pending"
        ]
        if pending_features:
            preview = "、".join(pending_features[:6])
            suffix = "…" if len(pending_features) > 6 else ""
            mapping_panel.caption(f"待选择：{preview}{suffix}")
    if report.get("ok"):
        st.session_state["post_feature_mapping_draft"] = copy.deepcopy(active)
        st.session_state["post_feature_mapping_confirmation"] = True
        st.session_state["post_feature_mapping_model_fingerprint"] = model_fingerprint
        st.session_state["post_feature_mapping_catalog_fingerprint"] = report.get("catalog_fingerprint")
    return (active if report.get("ok") else None), report


def _restore_versioned_molecular_feature_metadata(payload):
    if not isinstance(payload, dict):
        _clear_molecular_feature_session_metadata()
        return
    extra = payload.get("extra")
    extra = extra if isinstance(extra, dict) else {}
    workflow = (
        extra.get("molecular_feature_workflow")
        if "molecular_feature_workflow" in extra
        else payload.get("molecular_feature_workflow")
        if "molecular_feature_workflow" in payload
        else None
    )
    trace = (
        extra.get("molecular_feature_trace")
        if "molecular_feature_trace" in extra
        else payload.get("molecular_feature_trace")
        if "molecular_feature_trace" in payload
        else None
    )
    st.session_state["molecular_feature_workflow"] = workflow
    st.session_state["molecular_feature_trace"] = trace if trace is not None else []


def _restore_molecular_feature_metadata(payload, model_feature_cols=None):
    from core.virtual_screening import (
        resolve_molecular_feature_config,
        resolve_molecular_feature_workflow,
    )

    model_feature_cols = sanitize_feature_columns(model_feature_cols)
    _clear_molecular_feature_session_metadata()
    _restore_versioned_molecular_feature_metadata(payload)
    _restore_post_feature_mapping_metadata(
        payload,
        model_feature_cols=model_feature_cols,
    )
    workflow = resolve_molecular_feature_workflow(
        payload,
        model_feature_cols=model_feature_cols,
    )
    if workflow is not None:
        workflow_payload = workflow.to_dict()
        st.session_state["molecular_feature_workflow"] = workflow_payload
        config = workflow.to_legacy_config()
    else:
        config = resolve_molecular_feature_config(payload)
    st.session_state["molecular_feature_config"] = config
    return workflow, config


def _resolve_imported_molecular_feature_workflow(payload, model_feature_cols=None):
    from core.virtual_screening import resolve_molecular_feature_workflow

    if not isinstance(payload, dict):
        raise ValueError("导入的提取流程必须是 JSON 对象。")

    candidates = [payload]
    if isinstance(payload.get("workflow"), dict):
        candidates.insert(0, {"molecular_feature_workflow": payload["workflow"]})
    if isinstance(payload.get("molecular_feature_workflow"), dict):
        candidates.insert(0, payload)
    if payload.get("schema_version") and isinstance(payload.get("steps"), list):
        candidates.insert(0, {"molecular_feature_workflow": payload})
    if str(payload.get("method") or "").strip() or payload.get("feature_names"):
        candidates.append({"molecular_feature_config": payload})

    for candidate in candidates:
        workflow = resolve_molecular_feature_workflow(
            candidate,
            model_feature_cols=model_feature_cols,
        )
        if workflow is not None:
            return workflow
    raise ValueError("未在导入文件中找到可执行的分子特征提取 workflow。")


def _run_imported_molecular_feature_workflow(
    data,
    workflow_payload,
    *,
    device=None,
    progress_callback=None,
    model_feature_cols=None,
):
    """Replay an imported molecular-feature workflow on a dataframe."""
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")

    from core.molecular_feature_workflow import (
        execute_molecular_feature_workflow,
        find_duplicate_feature_names,
    )

    workflow = _resolve_imported_molecular_feature_workflow(
        workflow_payload,
        model_feature_cols=model_feature_cols,
    )
    source_df = data.reset_index(drop=True).copy()
    execution = execute_molecular_feature_workflow(
        source_df,
        workflow,
        device=device,
        mode="training_import",
        progress_callback=progress_callback,
    )
    features_df = execution.features.reset_index(drop=True)

    duplicate_features = find_duplicate_feature_names(features_df.columns.tolist())
    if duplicate_features:
        raise ValueError(
            "导入 workflow 生成了重复特征列："
            + ", ".join(duplicate_features[:12])
        )

    replace_cols = [col for col in features_df.columns if col in source_df.columns]
    if replace_cols:
        source_df = source_df.drop(columns=replace_cols)
    merged_df = pd.concat([source_df, features_df], axis=1)
    duplicate_merged = find_duplicate_feature_names(merged_df.columns.tolist())
    if duplicate_merged:
        raise ValueError(
            "导入 workflow 写回后存在重复列："
            + ", ".join(duplicate_merged[:12])
        )

    workflow_dict = workflow.to_dict()
    workflow_dict["workflow_hash"] = execution.workflow_hash or workflow_dict.get(
        "workflow_hash"
    )
    return {
        "data": merged_df,
        "features": features_df,
        "feature_names": features_df.columns.tolist(),
        "workflow": workflow_dict,
        "config": workflow.to_legacy_config(),
        "trace": execution.step_trace,
        "warnings": execution.warnings,
        "valid_row_indices": execution.valid_row_indices,
    }


def _build_prediction_molecular_baseline(
    source_values,
    workflow_payload,
    *,
    model_feature_cols=None,
    device=None,
):
    """Build one molecular prediction row by replaying the saved workflow."""
    workflow = _resolve_imported_molecular_feature_workflow(
        workflow_payload,
        model_feature_cols=model_feature_cols,
    )
    workflow_dict = workflow.to_dict()
    source_columns = collect_workflow_source_columns(workflow_dict)
    if not source_columns:
        raise ValueError("保存的分子特征流程没有声明可用的 SMILES/BigSMILES 来源列。")

    source_frame = build_single_row_source_frame(source_columns, source_values)
    source_report = validate_single_row_source_values(source_frame, source_columns)
    if not source_report.get("ok"):
        missing = source_report.get("missing_columns") or []
        empty = source_report.get("empty_columns") or []
        details = []
        if missing:
            details.append("缺少列：" + "、".join(missing))
        if empty:
            details.append("空值列：" + "、".join(empty))
        raise ValueError("分子输入不完整；" + "；".join(details))

    result = _run_imported_molecular_feature_workflow(
        source_frame,
        workflow_dict,
        device=device,
        mode="prediction",
        model_feature_cols=model_feature_cols,
    )
    result["source_columns"] = source_columns
    result["source_frame"] = source_frame
    result["source_report"] = source_report
    return result


def _render_prediction_molecular_input_panel(model_feature_cols):
    """Render manual resin/hardener source inputs for an imported workflow."""
    st.session_state["_prediction_requires_molecular_input"] = False
    workflow_payload = st.session_state.get("molecular_feature_workflow")
    if not isinstance(workflow_payload, dict):
        artifact = st.session_state.get("imported_model_artifact") or {}
        extra = artifact.get("extra") if isinstance(artifact, dict) else {}
        workflow_payload = extra.get("molecular_feature_workflow") if isinstance(extra, dict) else None
    if not isinstance(workflow_payload, dict):
        return None

    try:
        workflow = _resolve_imported_molecular_feature_workflow(
            workflow_payload,
            model_feature_cols=model_feature_cols,
        )
        source_columns = collect_workflow_source_columns(workflow.to_dict())
    except Exception as exc:
        st.warning(f"无法读取模型中的分子特征输入流程：{exc}")
        return None
    if not source_columns:
        st.warning("模型流程未声明树脂/固化剂的 SMILES 或 BigSMILES 来源列。")
        return None

    st.session_state["_prediction_requires_molecular_input"] = (
        workflow_requires_manual_molecular_input(workflow.to_dict())
    )

    role_labels = {
        "resin": "树脂/主体",
        "hardener": "固化剂",
        "neutral": "其他组分",
    }
    with st.expander("🧬 分子级配方输入（按训练 workflow 重放）", expanded=True):
        st.caption(
            "请手动输入与训练时对应的 SMILES/BigSMILES。系统严格按保存的步骤、顺序和参数提取，"
            "不会回退到 MACCS、Morgan 或零值。"
        )
        source_values = {}
        with st.form(key="prediction_molecular_input_form", clear_on_submit=False):
            input_columns = st.columns(2)
            for index, item in enumerate(source_columns):
                column = str(item["column"])
                roles = [role_labels.get(role, role) for role in item.get("roles", [])]
                role_text = " / ".join(roles) if roles else "分子来源"
                with input_columns[index % 2]:
                    source_values[column] = st.text_area(
                        f"{column}（{role_text}）",
                        value="",
                        height=86,
                        key=f"prediction_molecular_source_{index}",
                        help="保留原始 SMILES/BigSMILES 文本，不要输入分子名称或 CID。",
                    )
            submitted = st.form_submit_button(
                "提取分子特征并用于预测",
                type="primary",
                width="stretch",
            )

        if submitted:
            try:
                with st.spinner("正在按训练流程提取分子特征…"):
                    result = _build_prediction_molecular_baseline(
                        source_values,
                        workflow.to_dict(),
                        model_feature_cols=model_feature_cols,
                        device=st.session_state.get("compute_device"),
                    )
                st.session_state["_prediction_molecular_baseline"] = result
                st.success(
                    f"分子特征提取完成：生成 {len(result['feature_names'])} 个特征，"
                    f"workflow 顺序已保留。"
                )
            except Exception as exc:
                st.session_state.pop("_prediction_molecular_baseline", None)
                st.error(f"分子特征提取失败：{exc}")

        result = st.session_state.get("_prediction_molecular_baseline")
        if isinstance(result, dict):
            result_source_columns = result.get("source_columns") or []
            result_features = result.get("features")
            if isinstance(result_features, pd.DataFrame) and not result_features.empty:
                st.caption(
                    f"当前分子基线已就绪：{len(result_source_columns)} 个来源列，"
                    f"{result_features.shape[1]} 个提取特征。"
                )
                preview = result_features.iloc[:, : min(8, result_features.shape[1])]
                st.dataframe(preview, width="stretch", hide_index=True)
            for warning in result.get("warnings") or []:
                st.warning(warning)
            return result
    return st.session_state.get("_prediction_molecular_baseline")


