    def _summ_target_stats(values):
        if values is None:
            return None
        ser = pd.to_numeric(pd.Series(values), errors="coerce").dropna()
        if ser.empty:
            return None
        if len(ser) < 5:
            return {
                "min": float(ser.min()),
                "max": float(ser.max()),
            }
        return {
            "min": float(ser.min()),
            "max": float(ser.max()),
            "p01": float(np.quantile(ser, 0.01)),
            "p99": float(np.quantile(ser, 0.99)),
        }

